/// <summary>
/// PricingAttribute of table <c>PdsCatchWeightItem</c> field PdsCWMax.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributePdsCatchWeightItemPdsCWMax extends UPSPricingAttributePdsCatchWeightItem implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(PdsCatchWeightItem, PdsCWMax);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::Real);
    PdsCatchWeightItem pdsCatchWeightItem;

    while select pdsCatchWeightItem
        group by PdsCWMax
    {
        if (! ret.in(pdsCatchWeightItem.PdsCWMax))
        {
            ret.add(pdsCatchWeightItem.PdsCWMax);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(PdsCatchWeightItem, PdsCWMax));
    qbr.value(queryValue(_value));
}
